import { ChangeDetectionStrategy, Component, inject, output, signal } from '@angular/core';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';
import { VendorService } from '@org/api-services';
import { messageForError } from '@org/interceptors';
import { VendorFields } from '@org/shared-models';
import { CardComponent, CloseButtonComponent } from '@org/ui';
import { VendorFormComponent } from './vendor-form';

/**
 * The form for a new vendor, shown in the panel beside the list (platform U10, vendor spec R2-R6). The code is generated by the
 * server (R11). It reports the created vendor's id; the page opens it.
 */
@Component({
  selector: 'app-vendor-add',
  standalone: true,
  imports: [TranslatePipe, CardComponent, CloseButtonComponent, VendorFormComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="flex flex-col gap-5">
      <div class="flex items-center gap-3">
        <h1 class="mr-auto text-xl font-semibold text-primary-fg">{{ 'vendor.add.title' | translate }}</h1>
        <app-close-button [label]="'vendor.close' | translate" (clicked)="closed.emit()" />
      </div>
      <app-card>
        <app-vendor-form [saving]="saving()" [error]="error()" submitLabel="vendor.add.submit" (submitted)="add($event)" (cancelled)="closed.emit()" />
      </app-card>
    </div>
  `,
})
export class VendorAddComponent {
  private readonly vendors = inject(VendorService);
  private readonly translate = inject(TranslateService);

  readonly created = output<string>();
  readonly closed = output<void>();

  readonly saving = signal(false);
  readonly error = signal('');

  add(fields: VendorFields): void {
    this.saving.set(true);
    this.error.set('');
    this.vendors.create(fields).subscribe({
      next: (vendor) => {
        this.saving.set(false);
        this.created.emit(vendor.id);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.error.set(messageForError(error, this.translate));
      },
    });
  }
}
